import {perspectives} from './reflection.mjs';
// Choices exist only in this rendered scene, never in the progress snapshot.
export function renderReflection(root,finish){
 root.innerHTML=`<p class="eyebrow">IMAGINAR · COMPRENDER · PREGUNTAR</p><h4 id="reflection-title" tabindex="-1">La torre de Dani</h4><p>Dani construye una torre de bloques grandes. La torre se cae antes de poder enseñarla. Sam se acerca y pregunta: «¿Quieres compañía o prefieres un momento?».</p><p>Es una historia inventada. No hace falta hablar de ti ni contar algo que te haya ocurrido.</p><fieldset><legend>¿Qué podría sentir Dani? Puedes explorar varias ideas.</legend><div class="answer-options">${perspectives.map(p=>`<button type="button" class="answer-option" data-perspective="${p.id}" aria-pressed="false">${p.label}</button>`).join('')}</div></fieldset><div id="reflection-feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true"></div><div class="offline-idea"><h4>Una pregunta sin una única respuesta</h4><p>¿Ayudar siempre significa hacer algo, o a veces significa esperar? Imagina dos razones diferentes. Puedes conversar, señalar o quedarte pensando.</p></div><details><summary>Una ayuda para quien acompaña</summary><p>No adivines la emoción ni corrijas una vivencia. Habla del personaje: «¿Qué parte de la historia te hace pensar eso? ¿Qué otra explicación cabe?». No exigimos una respuesta moral única. No se evalúa la personalidad ni se ofrece terapia.</p></details><div class="controls"><button type="button" class="action primary" id="reflection-draw">Imaginar dos finales fuera de pantalla</button><button type="button" class="action secondary" id="reflection-pass">Prefiero no responder · cerrar</button></div><p class="quiet">Las ideas que pulses no se guardan; al salir o pausar se limpian. Solo se guarda si la sesión está abierta, en pausa o cerrada.</p>`;
 root.querySelectorAll('[data-perspective]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-perspective]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelector('#reflection-feedback').textContent=perspectives.find(p=>p.id===b.dataset.perspective).why+' No hay puntuación ni una única emoción correcta.';}));
 root.querySelector('#reflection-draw').addEventListener('click',finish);root.querySelector('#reflection-pass').addEventListener('click',finish);
}
